#pragma once
// Which release of the game is running, and where the port's addresses are in it.
//
// The port is written against the North American executable: every game address in the sources is that
// executable's. The PAL release (France, and Europe in English, Spanish and Italian: one executable, the
// same code) is a build of the same sources linked a little differently, so the same function or variable
// sits at a slightly different address. Once the executable is known, Va() turns a North American address
// into the running executable's (src/game/pal_map.inc, generated by tools/releases/pal_map.py).
//
// Addresses kept in named variables are declared with GAME_VA (or GAME_VAS for arrays) so they are
// translated in place when the release is chosen; anything else goes through Va() where it is used.
// Code the port compares with its own copy of the North American bytes is checked with MatchesCode, which
// accepts the PAL executable's relocated addresses.

#include <cstddef>
#include <cstdint>
#include <string>
#include <utility>

namespace swrots::game {

enum class Release : uint8_t {
    NorthAmerica, // USA, MD5 6460ef37862de3af364a0563a0a18c4e
    France,       // PAL, MD5 84ae8a86018f3ab4a1b5756b238cefd2
    Europe,       // PAL (English, Spanish, Italian), MD5 a48f65aa84a9848030b8644e1fd35b89
};

// The release with this default.xbe MD5, or false if the port does not support it.
bool FindRelease(const std::string& md5, Release* release);
// Chooses the running release (once per process, before anything uses a game address): translates every
// registered address variable.
void SelectRelease(Release release);
Release CurrentRelease();
// True once SelectRelease has run.
bool ReleaseKnown();
bool IsPal();
const char* ReleaseName(Release release);
// For messages: the supported releases.
extern const wchar_t* const kSupportedReleases;

// A North American address in the running executable (unchanged on the North American release; outside
// the game's image, e.g. 0, also unchanged). Fatal if the PAL executable has no such address, or if the
// release is not known yet (a static initialiser using a game address: see GAME_VA).
uint32_t Va(uint32_t northAmerica);
// The North American address of a running executable's address, or 0 if there is none (crash reports).
uint32_t NorthAmericaVa(uint32_t running);

// Registers a variable that holds a North American address (see GAME_VA); returns the address.
uint32_t RegisterVa(uint32_t* variable, uint32_t northAmerica);
// Registers a variable that holds the end of a North American address range, one past its last byte
// (see GAME_VA_END).
uint32_t RegisterVaEnd(uint32_t* variable, uint32_t northAmericaEnd);
// Registers an array of North American addresses (see GAME_VAS).
bool RegisterVas(uint32_t* first, size_t count);

// True if the running executable's code at `address` is `expected` (North American bytes), allowing
// for the PAL executable's own addresses in operands (absolute addresses, relative calls and jumps).
bool MatchesCode(uint32_t address, const void* expected, size_t length);

// A game function called through an address variable (GAME_VA), read at each call: unlike a function
// pointer made from it when the port starts, it follows the variable to the running release's address.
template <typename Fn> struct GameFunction {
    const uint32_t& address;
    template <typename... Args> decltype(auto) operator()(Args&&... args) const
    {
        return reinterpret_cast<Fn>(uintptr_t(address))(std::forward<Args>(args)...);
    }
};

} // namespace swrots::game

// A variable holding a North American game address, translated to the running release's.
#define GAME_VA(name, address) uint32_t name = ::swrots::game::RegisterVa(&name, address)
// The end of a range of North American game addresses (one past its last byte), translated likewise.
#define GAME_VA_END(name, address) uint32_t name = ::swrots::game::RegisterVaEnd(&name, address)
// After an array of North American addresses: registers it for translation.
#define GAME_VAS_CAT2(a, b) a##b
#define GAME_VAS_CAT(a, b) GAME_VAS_CAT2(a, b)
#define GAME_VAS(array) \
    static const bool GAME_VAS_CAT(kGameVas_, __COUNTER__) = \
        ::swrots::game::RegisterVas(array, sizeof(array) / sizeof((array)[0]))
